import { waitUntil } from "@vercel/functions";
import { db, demoLearnerId } from "../../../_lib/db.js";
import { updateDemoProfile } from "../../../_lib/performance.js";
import { allowMethod, assertAttemptId, enforceRateLimit, enforceSameOrigin, handleError, send } from "../../../_lib/http.js";
export default async function handler(req,res){ if(!allowMethod(req,res,"POST"))return; try{ enforceSameOrigin(req);enforceRateLimit(req,30);const id=assertAttemptId(req.query.id);const sql=db();const expected=Math.max(0,Math.min(500,Number(req.body?.expected_artifacts||0)));const artifacts=await sql`SELECT count(*)::int AS count FROM attempt_artifacts WHERE attempt_id=${id} AND status='active'`;if(expected&&Number(artifacts[0]?.count||0)<expected)throw Object.assign(new Error("Expected attempt artifacts have not all synchronized"),{statusCode:409});const rows=await sql`UPDATE learning_attempts SET sync_status='complete',updated_at=now() WHERE attempt_id=${id} AND learner_id=${demoLearnerId()} AND sync_status<>'complete' RETURNING repository_attempt_id`;if(rows.length){waitUntil(updateDemoProfile(id));return send(res,200,{repository_attempt_id:rows[0].repository_attempt_id,sync_status:"complete"});}const existing=await sql`SELECT repository_attempt_id FROM learning_attempts WHERE attempt_id=${id} AND learner_id=${demoLearnerId()}`;if(!existing.length)throw Object.assign(new Error("Attempt not found"),{statusCode:404});send(res,200,{repository_attempt_id:existing[0].repository_attempt_id,sync_status:"complete",idempotent:true});}catch(error){handleError(res,error);} }
